//! Deliveries run concurrently, at most [`MAX_CONCURRENT_DELIVERIES`] at a
//! time, each bounded by [`DELIVERY_TIMEOUT`], and the whole change by
//! [`DISPATCH_BUDGET`]. There are no retries: every subscriber gets exactly
//! one [`DeliveryEvent`] in the [`DeliverySink`], and one that is not
//! delivered, including one not reached before the budget ran out, is
//! recorded as [`Outcome::Failed`].
//!
//! The canary is a platform subscription on the instance's loopback that
//! receives every change, sent after the subscriber lookup through the same
//! transport as the change's subscribers. [`Notifier::canary_healthy`] is the
//! notifier's health check: green only if, for the most recent change, the
//! canary acknowledged and every subscriber was looked up and attempted
//! within the budget. A relying party's own failure is reported in its
//! delivery event, not in the health check.

use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::time::Duration;

use serde_json::json;
use tokio::task::JoinSet;
use tokio::time::{timeout_at, Instant};

use crate::settings::{Setting, SettingsStore};
use crate::status::StatusChange;
use crate::webhook::WebhookTransport;

/// How long one status change may take, lookup and fan-out together. The
/// deployed function is killed at 10 s from the start of its invocation
/// (`timeout_seconds` in the deployment configuration); this leaves room for
/// the invocation's start-up and for recording what was not delivered.
pub const DISPATCH_BUDGET: Duration = Duration::from_secs(7);

/// How long one delivery may take, connect included (the platform's own
/// connect timeout is 2 s). An endpoint that accepts the connection and never
/// answers is given up on after this.
pub const DELIVERY_TIMEOUT: Duration = Duration::from_secs(3);

/// Deliveries in flight at once for one change. With [`DELIVERY_TIMEOUT`]
/// inside [`DISPATCH_BUDGET`], two full rounds of non-answering endpoints
/// (32) still leave every subscriber attempted; healthy endpoints go through
/// at 16 per round trip. Across the 20 instances the deployment allows, that
/// is at most 320 connections through the shared NAT gateways.
pub const MAX_CONCURRENT_DELIVERIES: usize = 16;

/// Setting kind of a webhook subscription.
pub const WEBHOOK_KIND: &str = "webhook";

pub const CANARY_ID: &str = "canary";
/// The canary receiver the platform operates on the instance's loopback,
/// behind the same outbound client as the subscribers' calls.
pub const CANARY_URL: &str = "http://127.0.0.1/webhooks/canary";

